import math


def ideal_ratio_mask(a_mag, b_mag, eps=1e-8):
    if len(a_mag) != len(b_mag):
        raise ValueError("the two spectrograms must have the same shape")
    mask = []
    for row_a, row_b in zip(a_mag, b_mag):
        if len(row_a) != len(row_b):
            raise ValueError("the two spectrograms must have the same shape")
        mask.append([a / (a + b + eps) for a, b in zip(row_a, row_b)])
    return mask


def apply_mask(mask, mix_mag):
    if len(mask) != len(mix_mag):
        raise ValueError("the mask and the mixture must have the same shape")
    out = []
    for mask_row, mix_row in zip(mask, mix_mag):
        if len(mask_row) != len(mix_row):
            raise ValueError("the mask and the mixture must have the same shape")
        out.append([weight * value for weight, value in zip(mask_row, mix_row)])
    return out


def si_sdr(reference, estimate, eps=1e-8):
    if len(reference) != len(estimate):
        raise ValueError("reference and estimate must be the same length")
    if not reference:
        raise ValueError("empty signals cannot be scored")
    ref_mean = sum(reference) / len(reference)
    est_mean = sum(estimate) / len(estimate)
    ref = [value - ref_mean for value in reference]
    est = [value - est_mean for value in estimate]
    energy = sum(value * value for value in ref)
    alpha = sum(e * r for e, r in zip(est, ref)) / (energy + eps)
    target = [alpha * value for value in ref]
    noise = [e - t for e, t in zip(est, target)]
    numerator = sum(value * value for value in target) + eps
    denominator = sum(value * value for value in noise) + eps
    return 10 * math.log10(numerator / denominator)


def separation_gain(reference, mixture, estimate):
    return si_sdr(reference, estimate) - si_sdr(reference, mixture)
